    SELECT COALESCE(MAX(id) + 1, 1) INTO v_next_id FROM carbon_emissions;

    FOR v_ac_id, v_cooling, v_heating, v_power, v_eer, v_refrigerant IN
        SELECT ac_id, cooling_capacity_btu, heating_capacity_btu,
               power_consumption_watts, energy_efficiency_ratio, refrigerant_type
        FROM air_conditioner_info
        ORDER BY ac_id
    LOOP
        IF para_target_mode = 'Heating' THEN
            v_working := v_heating;
        ELSE
            v_working := v_cooling;
        END IF;

        SELECT phase_change_heat_kj_per_kg, refrigerant_flow_rate_kg_per_s
        INTO v_phase, v_flow
        FROM refrigerant_properties
        WHERE refrigerant_type = v_refrigerant;

        IF v_phase IS NOT NULL AND v_flow IS NOT NULL THEN
            IF v_working IS NOT NULL AND v_working <> 0 THEN
                v_capacity_ratio := (v_phase * v_flow * 3412.14) / v_working;
            ELSE
                v_capacity_ratio := NULL;
            END IF;
            IF v_power IS NOT NULL AND v_power <> 0 THEN
                v_actual_eff := v_working / v_power;
            ELSE
                v_actual_eff := NULL;
            END IF;
        ELSE
            v_capacity_ratio := 1.0;
            v_actual_eff := v_eer;
        END IF;

        IF v_actual_eff IS NOT NULL THEN
            v_actual_cop := v_actual_eff / 3.412;
        ELSE
            v_actual_cop := NULL;
        END IF;

        SELECT COALESCE(SUM(energy_consumption_kwh), 0),
               COUNT(DISTINCT record_date),
               AVG(indoor_temperature_celsius),
               AVG(outdoor_temperature_celsius),
               AVG(temperature_setting_celsius),
               COUNT(*)
        INTO v_total, v_sample_days, v_avg_indoor, v_avg_outdoor, v_avg_setting, v_count
        FROM energy_consumption
        WHERE ac_id = v_ac_id AND mode = para_target_mode;

        IF v_count = 0 THEN
            v_total := 0;
            v_sample_days := 0;
            v_avg_indoor := NULL;
            v_avg_outdoor := NULL;
            v_avg_setting := NULL;
        END IF;

        v_flag := false;
        IF v_avg_indoor IS NOT NULL AND v_avg_setting IS NOT NULL THEN
            IF para_target_mode = 'Cooling' AND (v_avg_indoor - v_avg_setting) > 2.0 THEN
                v_flag := true;
            ELSIF para_target_mode = 'Heating' AND (v_avg_setting - v_avg_indoor) > 2.0 THEN
                v_flag := true;
