                CASE WHEN v_capacity_ratio IS NOT NULL AND v_capacity_ratio > 0
                     THEN 1.0 / v_capacity_ratio ELSE 1.0 END
            )
            WHERE ac_id = v_ac_id AND mode = para_target_mode;

            IF v_capacity_ratio < 0.85 THEN
                UPDATE air_conditioner_info
                SET power_consumption_watts = power_consumption_watts * LEAST(1.5, 1.0 + (1.0 - v_capacity_ratio))
                WHERE ac_id = v_ac_id;
